import { colophonText, renderParameters, renderStatement } from "./base";
import type { ReportSkin } from "./types";

/**
 * Classic — a traditional accounting-firm letterhead.
 *
 * Black ink on white, Georgia throughout, ruled rather than shaded: the look of
 * a statement typed up by a practice rather than generated by software. It is
 * the cheapest of the themes to print and the only one that survives a fax or a
 * photocopier intact, so it is the right default for anything going to paper.
 *
 * The reference template reaches this look with no webfont at all, so nothing
 * here needed substituting. Its preset is near-black rather than a colour, so
 * the template is monochrome by what it is rather than by opting out of
 * something.
 */
const styles = `
  html, body {
    font-family: var(--font-display);
    color: #000;
    font-size: 10pt;
  }

  .letterhead {
    text-align: center;
    padding-bottom: 7pt;
    margin-bottom: 3pt;
  }

  .org {
    font-size: 15pt;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 3pt;
  }

  /* The double rule under a practice letterhead: one heavy, one hair.
     The UA gives <hr> an inset border on all four sides, so it is cleared
     before a single edge is drawn — otherwise the rule prints as a flat box. */
  .rule-heavy,
  .rule-hair {
    border: none;
    height: 0;
  }

  .rule-heavy {
    border-top: 1.5pt solid #000;
    margin: 0;
  }

  .rule-hair {
    border-top: 0.5pt solid #000;
    margin: 1.5pt 0 12pt;
  }

  .title {
    text-align: center;
    font-size: 13pt;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin: 0 0 3pt;
  }

  .note {
    text-align: center;
    font-size: 9.5pt;
    font-style: italic;
    color: #333;
    margin: 0 0 12pt;
  }

  .params {
    margin: 0 0 12pt;
    padding: 0;
    list-style: none;
    text-align: center;
    font-size: 8.5pt;
    font-style: italic;
    color: #555;
  }

  th {
    font-family: var(--font-display);
    font-size: 8.5pt;
    font-weight: 700;
    font-variant: small-caps;
    letter-spacing: 0.06em;
    color: #000;
    border-top: 1pt solid #000;
    border-bottom: 0.5pt solid #000;
    padding: 4pt 6pt;
  }

  td { border-bottom: 0.5pt solid #ddd; }

  .row-section td {
    font-size: 10.5pt;
    font-variant: small-caps;
    letter-spacing: 0.05em;
  }

  .row-subtotal td { border-top: 0.5pt solid #000; }

  .row-total td {
    font-size: 10.5pt;
    border-top: 1pt solid #000;
    border-bottom: 2.5pt double #000;
  }

  .empty { color: #555; }

  .colophon {
    margin-top: 16pt;
    padding-top: 5pt;
    border-top: 0.5pt solid #000;
    font-size: 8pt;
    font-style: italic;
    color: #555;
    display: flex;
    justify-content: space-between;
    gap: 12pt;
  }

  .colophon p { margin: 0; }

  .section { margin-bottom: 13pt; }

  .section h3 {
    margin: 0 0 5pt;
    font-size: 11pt;
    font-weight: 700;
    font-variant: small-caps;
    letter-spacing: 0.07em;
    color: #000;
    break-after: avoid;
  }
`;

export const classicSkin: ReportSkin = {
  id: "classic",
  label: "Classic",
  description: "Traditional serif letterhead, black ink, ruled not shaded.",
  fonts: { body: "serif", display: "serif" },
  styles,

  renderShell(context) {
    const { orgName, title, note, parameters, generatedAt, currencyNote, esc } = context;

    return `<div class="doc">
      <header class="letterhead">
        <p class="org">${esc(orgName)}</p>
      </header>
      <hr class="rule-heavy" />
      <hr class="rule-hair" />

      <h1 class="title">${esc(title)}</h1>
      <p class="note">${esc(note)}</p>
      ${renderParameters(parameters, esc)}

      ${renderStatement(context, (section, esc) =>
      `<section class="section">
        ${section.heading ? `<h3>${esc(section.heading)}</h3>` : ""}
        ${section.table}
      </section>`
    )}

      <footer class="colophon">
        <p>${esc(orgName)} · ${esc(title)}</p>
        <p>${esc(colophonText(generatedAt, currencyNote))}</p>
      </footer>
    </div>`;
  },
};
